<section class="page-head"><div><p class="eyebrow">NSG PROCUREMENT</p><h1><?= e($title) ?></h1></div></section><?php if($flash):?><div class="alert success"><?=e($flash)?></div><?php endif?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><div class="grid two"><section class="panel"><h2>Create <?=e(rtrim($title,'s'))?></h2><form method="post" action="<?=e(url($action))?>"><?=csrf_field()?><?php foreach($fields as $name=>$meta):?><label><?=e($meta['label'])?><?php if($meta['type']==='textarea'):?><textarea name="<?=e($name)?>" <?=!empty($meta['required'])?'required':''?>></textarea><?php else:?><input name="<?=e($name)?>" type="<?=e($meta['type'])?>" <?=!empty($meta['required'])?'required':''?> step="any"><?php endif?></label><?php endforeach?><button class="btn primary">Save record</button></form></section><section class="panel"><h2>Records</h2><div class="table-wrap"><table><thead><tr><?php foreach($columns as $c):?><th><?=e(ucwords(str_replace('_',' ',$c)))?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($columns as $c):?><td><?=e($row[$c]??'—')?></td><?php endforeach?></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="<?=count($columns)?>">No records yet.</td></tr><?php endif?></tbody></table></div></section></div>
